INSERT INTO `onl_drag_comp` VALUES ('708976410864304129', '708970414976712704', '甘特图', 'JCommon', 'ant-design:appstore-twotone', 100, NULL, '{\n  \"dataType\": 1,\n  \"h\": 55,\n  \"background\": \"#ffffff\",\n  \"url\": \"http://api.jeecg.com/mock/33/chart\",\n  \"timeOut\": 0,\n  \"turnConfig\": {\n    \"url\": \"\"\n  },\n  \"customOption\": \"option={\'backgroundColor\':\'#fff\',\'title\':{\'text\':\'工程项目工期\',\'padding\':20,\'textStyle\':{\'fontSize\':17,\'fontWeight\':\'bolder\',\'color\':\'#333\'},\'subtextStyle\':{\'fontSize\':13,\'fontWeight\':\'bolder\'}},\'legend\':{\'data\':[\'计划工期\',\'可行性研究阶段\',\'初步设计阶段\',\'施工图设计阶段\',\'项目实施阶段\',\'项目验收阶段\'],\'align\':\'right\',\'right\':80,\'top\':50},\'grid\':{\'containLabel\':true,\'show\':false,\'right\':130,\'left\':40,\'bottom\':40,\'top\':90},\'xAxis\':{\'type\':\'time\',\'axisLabel\':{\'show\':true,\'interval\':0},\'axisLine\':{\'show\':true}},\'yAxis\':{\'axisLabel\':{\'show\':true,\'interval\':0,\'formatter\':function(value,index){var last=\'\';var max=5;var len=value.length;var hang=Math.ceil(len/max);if(hang>1){for(var i=0;i<hang;i++){var start=i*max;var end=start+max;var temp=value.substring(start,end)+\'\';last+=temp;}return last;}else{return value;}}},\'data\':[\'临夏自治州2015年度治理工程项目\',\'标段一\',\'标段二\']},\'tooltip\':{\'trigger\':\'axis\',\'formatter\':function(params){var res=\'\';var name=\'\';var start0=\'\';var start=\'\';var end0=\'\';var end=\'\';for(var i in params){var k=i%2;if(!k){start0=params[i].data;start=start0.getFullYear()+\'-\'+(start0.getMonth()+1)+\'-\'+start0.getDate();}if(k){name=params[i].seriesName;end0=params[i].data;end=end0.getFullYear()+\'-\'+(end0.getMonth()+1)+\'-\'+end0.getDate();res+=name+\' : \'+start+\'~\'+end+\'</br>\';}}return res;}},\'series\':[{\'name\':\'计划工期\',\'type\':\'bar\',\'stack\':\'总量0\',\'label\':{\'normal\':{\'show\':true,\'color\':\'#000\',\'position\':\'right\',\'formatter\':function(params){return params.seriesName}}},\'itemStyle\':{\'normal\':{\'color\':\'skyblue